def find_u_shapes(grid):
    """Find U-shapes in grid. Return topmost unique ones."""
    rows = len(grid)
    cols = len(grid[0])
    u_shapes = []

    for r in range(rows):
        positions = [(r, c) for c in range(cols) if grid[r][c] == 5]
        if len(positions) < 2:
            continue
        left_col = positions[0][1]
        right_col = positions[-1][1]

        if left_col == right_col:
            continue

        # Find bottom
        bottom = r + 1
        while bottom < rows:
            if grid[bottom][left_col] == 5 and grid[bottom][right_col] == 5:
                bottom += 1
            else:
                break
        bottom -= 1

        if bottom >= r and bottom < rows:
            interior = list(range(left_col + 1, right_col))
            if len(interior) >= 1:
                u_shapes.append({
                    'top_row': r,
                    'bottom_row': bottom,
                    'left_col': left_col,
                    'right_col': right_col,
                    'interior_cols': interior,
                    'rows': rows,
                    'cols': cols
                })

        # Skip ahead
        r = bottom

    # Group by (left, right) and keep topmost
    seen = {}
    for u in u_shapes:
        key = (u['left_col'], u['right_col'])
        if key not in seen or u['top_row'] < seen[key]['top_row']:
            seen[key] = u

    return list(seen.values())

def compute_fill_range(u):
    """Compute the fill range for a U-shape."""
    cols = u['cols']
    interior = u['interior_cols']
    interior_start = interior[0]
    interior_end = interior[-1]

    left_gap = interior_start
    right_gap = cols - interior_end - 1

    if right_gap > left_gap:
        return (0, interior_end)
    else:
        return (interior_start, cols - 1)

